p=argparse.ArgumentParser();p.add_argument('--native');p.add_argument('--dotnet');p.add_argument('--reference');p.add_argument('--work',type=pathlib.Path);a=p.parse_args();a.work=a.work.resolve();a.work.mkdir(parents=True,exist_ok=True);owned=pathlib.Path(tempfile.mkdtemp(prefix='owned-files-',dir=a.work))
